from urllib.request import urlopen
from urllib.error import HTTPError,URLError
from hashlib import sha256
from pathlib import Path
for endpoint in ['/health','/vault','/api/personal/details','/api/invite','/assets/vault.js']:
    try:
        with urlopen('http://127.0.0.1:8767'+endpoint,timeout=5) as response:
            body=response.read()
            result={'endpoint':endpoint,'status':response.status}
            if endpoint=='/assets/vault.js':
                result['matches_workspace']=sha256(body).digest()==sha256(Path('runtime/vault/vault.js').read_bytes()).digest()
            print(result)
    except HTTPError as error: print({'endpoint':endpoint,'status':error.code})
    except URLError as error: print({'endpoint':endpoint,'error':str(error.reason)})
