};
let personalKind='';
let personalState={};
const personalFields={email:{email:'personal-email'},phone:{phone_number:'personal-phone',country_code:'personal-country-code'},address:{address_line1:'personal-line1',address_line2:'personal-line2',city:'personal-city',state:'personal-state',postal_code:'personal-postal',country:'personal-country'}};
